import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Search, MapPin, Phone, ArrowLeft, TrendingUp, Plus, Compass, Bookmark, User, Camera,
  CheckCircle2, X, Store, Clock3, Sparkles, Moon, Sun, Monitor, Bell, Settings,
  LogOut, Package, ShieldCheck, Star, SlidersHorizontal, ChevronRight,
  BarChart3, LocateFixed, Navigation, ExternalLink, MessageSquare, Edit3, Save, Menu, AlertTriangle, RefreshCw, CalendarClock
} from 'lucide-react';

const API_BASE = import.meta.env.VITE_API_BASE || 'http://localhost:5000/api';
const GOOGLE_MAPS_API_KEY = import.meta.env.VITE_GOOGLE_MAPS_API_KEY || '';
const DEFAULT_LOCATION = {lat:22.7196,lng:75.8577,label:'Bada Bazaar, Indore'};
const DEMO = {
  CUSTOMER: { email: 'demo@gramsetu.app', password: 'Demo@12345' },
  BUSINESS_OWNER: { email: 'business@gramsetu.app', password: 'Business@12345' },
  ADMIN: { email: 'admin@gramsetu.app', password: 'Admin@12345' }
};
const categories = [
  ['ALL','All / सब','🏪'],['Books & Stationery','Books','📚'],['Grocery','Grocery','🛒'],['Beauty & Barber','Salon','✂️'],
  ['Tailor','Tailor','🧵'],['Mobile Repair','Mobile','📱'],['Bakery','Bakery','🥐'],['Hardware','Hardware','🔧'],['Home Services','Services','🏠'],['Agriculture & Tools','Kisan','🚜']
];
const i18n = {
  en:{tagline:'Know price. Know stock. Buy nearby.',search:"Search products, services, or local shops…",nearby:'Nearby local businesses',open:'Open now',closed:'Closed',save:'Save',saved:'Saved',login:'Sign in',demo:'Try demo',notifications:'Notifications',profile:'Profile',reviews:'Reviews',catalog:'Catalog & pricing',hours:'Opening hours',dashboard:'Business dashboard',dark:'Theme'},
  hi:{tagline:'दुकान पास, भाव साफ़, सामान पक्का।',search:'सामान, सेवा या स्थानीय दुकान खोजें…',nearby:'आपके आस-पास की दुकानें',open:'अभी खुला',closed:'बंद',save:'सहेजें',saved:'सहेजा गया',login:'लॉग इन',demo:'डेमो आज़माएँ',notifications:'सूचनाएँ',profile:'प्रोफ़ाइल',reviews:'समीक्षाएँ',catalog:'कैटलॉग और भाव',hours:'खुलने का समय',dashboard:'दुकानदार डैशबोर्ड',dark:'थीम'}
};

function App(){
  const [theme,setTheme]=useState(localStorage.getItem('mh-theme')||'system');
  const [lang,setLang]=useState(localStorage.getItem('mh-lang')||'en');
  const [user,setUser]=useState(null); const [token,setToken]=useState(localStorage.getItem('mh-token')||'');
  const [page,setPage]=useState('home'); const [query,setQuery]=useState(''); const [category,setCategory]=useState('ALL');
  const [businesses,setBusinesses]=useState([]); const [selected,setSelected]=useState(null); const [loading,setLoading]=useState(true); const [error,setError]=useState('');
  const [saved,setSaved]=useState({businesses:[],items:[]}); const [notifications,setNotifications]=useState([]); const [authOpen,setAuthOpen]=useState(false);
  const [customerLocation,setCustomerLocation]=useState(()=>{try{return JSON.parse(localStorage.getItem('mh-location'))||DEFAULT_LOCATION}catch{return DEFAULT_LOCATION}});
  const [locating,setLocating]=useState(false); const [locationMessage,setLocationMessage]=useState('');
  const t=i18n[lang];
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('mh-theme',theme)},[theme]);
  useEffect(()=>{localStorage.setItem('mh-lang',lang)},[lang]);
  useEffect(()=>{if(token) api('/auth/me').then(x=>setUser(x.user)).catch(()=>{localStorage.removeItem('mh-token');setToken('')})},[]);
  useEffect(()=>{loadBusinesses()},[query,category,customerLocation?.lat,customerLocation?.lng]);
  useEffect(()=>{if(user){loadSaved();loadNotifications()}},[user]);
  async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(`${API_BASE}${path}`,{...opts,headers});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Request failed');return data}
  async function loadBusinesses(){setLoading(true);setError('');try{const d=await api(`/businesses?q=${encodeURIComponent(query)}&category=${encodeURIComponent(category==='ALL'?'':category)}&lat=${encodeURIComponent(customerLocation?.lat||'')}&lng=${encodeURIComponent(customerLocation?.lng||'')}`);setBusinesses(d);if(query&&user)api('/search-events',{method:'POST',body:JSON.stringify({query})}).catch(()=>{})}catch(e){setError(e.message)}finally{setLoading(false)}}
  async function loadSaved(){try{setSaved(await api('/saved'))}catch{}}
  async function loadNotifications(){try{setNotifications(await api('/notifications'))}catch{}}
  function chooseCustomerLocation(next){setCustomerLocation(next);localStorage.setItem('mh-location',JSON.stringify(next))}
  async function useMyLocation(){setLocationMessage('');if(!navigator.geolocation){setLocationMessage('Location is not supported by this browser.');return}setLocating(true);navigator.geolocation.getCurrentPosition(pos=>{const next={lat:Number(pos.coords.latitude.toFixed(6)),lng:Number(pos.coords.longitude.toFixed(6)),label:'Your current location'};chooseCustomerLocation(next);setLocationMessage('Using your current location.');setLocating(false)},err=>{setLocationMessage(err.code===1?'Location permission was denied. You can still browse nearby businesses.':'Unable to get your location. Try again or use the default area.');setLocating(false)},{enableHighAccuracy:true,timeout:10000,maximumAge:300000})}
  async function login(email,password){const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})});localStorage.setItem('mh-token',d.token);setToken(d.token);setUser(d.user);setAuthOpen(false);setPage(d.user.role==='BUSINESS_OWNER'?'dashboard':d.user.role==='ADMIN'?'admin':'home')}
  async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}localStorage.removeItem('mh-token');setToken('');setUser(null);setPage('home')}
  const [savingIds,setSavingIds]=useState(new Set());
  async function toggleSave(b){if(!user){setAuthOpen(true);return}const id=b.id; if(savingIds.has(id))return; const exists=saved.businesses.some(x=>x.id===id); const previous=saved; setSavingIds(prev=>new Set(prev).add(id)); setSaved(prev=>exists?{...prev,businesses:prev.businesses.filter(x=>x.id!==id)}:{...prev,businesses:[...prev.businesses,b]}); try{await api(`/saved/business/${id}`,{method:exists?'DELETE':'POST'}); await loadSaved()}catch(e){setSaved(previous)}finally{setSavingIds(prev=>{const n=new Set(prev);n.delete(id);return n})}}
  async function openBusiness(b){try{setSelected(await api(`/businesses/${b.id}`));setPage('business')}catch(e){setError(e.message)}}
  const savedIds=useMemo(()=>new Set(saved.businesses.map(x=>x.id)),[saved]);
  return <div className="app-shell">
    <header className="topbar">
      <button className="brand" onClick={()=>{setPage('home');setSelected(null)}}><span className="brand-mark">MH</span><span><b>Market Hub</b><small>{t.tagline}</small></span></button>
      <div className="top-actions"><button className="icon-btn" title="Language" onClick={()=>setLang(x=>x==='en'?'hi':'en')}>{lang==='en'?'हिन्दी':'EN'}</button><ThemeButton theme={theme} setTheme={setTheme}/>{user?<button className="avatar" onClick={()=>setPage('profile')}>{(user.name||'U')[0].toUpperCase()}</button>:<button className="primary small" onClick={()=>setAuthOpen(true)}>{t.login}</button>}</div>
    </header>
    {error&&<div className="error-banner"><AlertTriangle size={16}/>{error}<button onClick={()=>setError('')}><X size={15}/></button></div>}
    <main className="content">
      {page==='home'&&<Home query={query} setQuery={setQuery} category={category} setCategory={setCategory} businesses={businesses} loading={loading} openBusiness={openBusiness} savedIds={savedIds} toggleSave={toggleSave} savingIds={savingIds} t={t} customerLocation={customerLocation} locating={locating} useMyLocation={useMyLocation} locationMessage={locationMessage} setCustomerLocation={chooseCustomerLocation}/>} 
      {page==='business'&&selected&&<Business business={selected} onBack={()=>setPage('home')} saved={savedIds.has(selected.id)} toggleSave={()=>toggleSave(selected)} user={user} api={api} refresh={()=>openBusiness(selected)} t={t} customerLocation={customerLocation} setCustomerLocation={chooseCustomerLocation}/>} 
      {page==='saved'&&<Saved saved={saved} businesses={businesses} openBusiness={openBusiness} toggleSave={toggleSave} savedIds={savedIds} api={api} refreshSaved={loadSaved} t={t}/>} 
      {page==='notifications'&&<Notifications notifications={notifications} refresh={loadNotifications} api={api} t={t}/>} 
      {page==='profile'&&<Profile user={user} logout={logout} setTheme={setTheme} theme={theme} setPage={setPage} t={t}/>} 
      {page==='dashboard'&&user?.role==='BUSINESS_OWNER'&&<BusinessDashboard api={api} logout={logout} t={t}/>} 
      {page==='admin'&&user?.role==='ADMIN'&&<AdminDashboard api={api} t={t}/>} 
    </main>
    <nav className="bottom-nav"><NavButton icon={<Compass/>} label="Home" active={page==='home'} onClick={()=>setPage('home')}/><NavButton icon={<Bookmark/>} label="Saved" active={page==='saved'} onClick={()=>user?setPage('saved'):setAuthOpen(true)}/><NavButton icon={<Bell/>} label="Alerts" active={page==='notifications'} onClick={()=>user?setPage('notifications'):setAuthOpen(true)}/><NavButton icon={<User/>} label="Profile" active={page==='profile'} onClick={()=>user?setPage('profile'):setAuthOpen(true)}/></nav>
    {authOpen&&<AuthModal onClose={()=>setAuthOpen(false)} onLogin={login} onRegister={async(d)=>{await api('/auth/register',{method:'POST',body:JSON.stringify(d)});await login(d.email,d.password)}}/>}
  </div>
}
function NavButton({icon,label,active,onClick}){return <button className={active?'nav-btn active':'nav-btn'} onClick={onClick}>{React.cloneElement(icon,{size:20})}<span>{label}</span></button>}
function ThemeButton({theme,setTheme}){return <button className="icon-btn" title="Theme" onClick={()=>setTheme(theme==='light'?'dark':theme==='dark'?'system':'light')}>{theme==='dark'?<Moon size={17}/>:theme==='light'?<Sun size={17}/>:<Monitor size={17}/>}</button>}
function Home({query,setQuery,category,setCategory,businesses,loading,openBusiness,savedIds,toggleSave,savingIds,t,customerLocation,locating,useMyLocation,locationMessage,setCustomerLocation}){return <div className="stack">
  <section className="hero"><div><span className="eyebrow">LOCAL DISCOVERY</span><h1>Find what you need,<br/><span>nearby.</span></h1><p>Compare local prices, real availability, hours and community feedback before you go.</p></div><div className="hero-orb">⌁</div></section>
  <div className="search-wrap"><Search size={19}/><input id="market-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder={t.search}/>{query&&<button onClick={()=>setQuery('')}><X size={17}/></button>}</div>
  <LocationBar location={customerLocation} locating={locating} onLocate={useMyLocation} message={locationMessage}/>
  <GoogleMapView businesses={businesses} customerLocation={customerLocation} homeServices={category==='Home Services'} openBusiness={openBusiness} onLocationChange={setCustomerLocation}/>
  <div className="chips">{categories.map(([id,label,icon])=><button key={id} className={category===id?'chip active':'chip'} onClick={()=>setCategory(id)}><span>{icon}</span>{label}</button>)}</div>
  {!query&&<section className="demand-card"><div><div className="eyebrow warm">COMMUNITY SIGNAL</div><b>People nearby are searching for school books, thermos bottles and grooming services.</b><p>Demand insights are aggregated; individual searches are never exposed.</p></div><TrendingUp size={28}/></section>}
  {category==='Home Services'&&!query&&<HomeServiceRadar businesses={businesses} openBusiness={openBusiness} savedIds={savedIds} toggleSave={toggleSave} savingIds={savingIds} t={t}/>}
  <section><div className="section-head"><div><h2>{t.nearby}</h2><small>{businesses.length} local options</small></div><SlidersHorizontal size={18}/></div>
  {loading?<Loading/>:businesses.length===0?<Empty text="We couldn't find this nearby. Try another search or expand your area."/>:<div className="business-grid">{businesses.map(b=><BusinessCard key={b.id} b={b} openBusiness={openBusiness} saved={savedIds.has(b.id)} saving={savingIds.has(b.id)} toggleSave={toggleSave} t={t}/>)}</div>}</section>
  {query.trim()&&<ProductSearchListings query={query} businesses={businesses} openBusiness={openBusiness}/>}
</div>}
function LocationBar({location,locating,onLocate,message}){return <section className="location-bar panel"><div className="location-main"><div className="location-icon"><Navigation size={18}/></div><div><span className="eyebrow">YOUR LOCATION</span><b>{location?.label||'Choose your location'}</b><small>{location?.lat&&location?.lng?`${Number(location.lat).toFixed(5)}, ${Number(location.lng).toFixed(5)}`:'Location not set'}</small></div></div><div className="location-actions"><button className="secondary small" onClick={onLocate} disabled={locating}>{locating?<RefreshCw size={15} className="spin"/>:<LocateFixed size={15}/>} {locating?'Locating…':'Use my location'}</button><a className="icon-btn" href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${location?.lat||DEFAULT_LOCATION.lat},${location?.lng||DEFAULT_LOCATION.lng}`)}`} target="_blank" rel="noreferrer" title="Open location in Google Maps"><ExternalLink size={15}/></a></div>{message&&<small className="location-message">{message}</small>}</section>}

function GoogleMapView({businesses,customerLocation,homeServices,openBusiness,onLocationChange}){const [expanded,setExpanded]=useState(false);const ref=useRef(null);const mapRef=useRef(null);const markersRef=useRef([]);const circlesRef=useRef([]);const infoRef=useRef(null);const [ready,setReady]=useState(false);const [mapError,setMapError]=useState('');
  useEffect(()=>{let cancelled=false;if(!GOOGLE_MAPS_API_KEY){setMapError('Add VITE_GOOGLE_MAPS_API_KEY to frontend/.env to enable the live Google Map. The location and service coverage data still work without the key.');return}if(window.google?.maps){setReady(true);return}const existing=document.getElementById('google-maps-script');if(existing){existing.addEventListener('load',()=>!cancelled&&setReady(true));existing.addEventListener('error',()=>!cancelled&&setMapError('Google Maps could not be loaded. Check your API key and Maps JavaScript API access.'));return ()=>{cancelled=true}}const script=document.createElement('script');script.id='google-maps-script';script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(GOOGLE_MAPS_API_KEY)}&v=weekly`;script.async=true;script.defer=true;script.onload=()=>!cancelled&&setReady(true);script.onerror=()=>!cancelled&&setMapError('Google Maps could not be loaded. Check your API key and Maps JavaScript API access.');document.head.appendChild(script);return()=>{cancelled=true}},[]);
  useEffect(()=>{if(!expanded){mapRef.current=null;markersRef.current.forEach(m=>m.setMap(null));circlesRef.current.forEach(c=>c.setMap(null));markersRef.current=[];circlesRef.current=[];if(infoRef.current)infoRef.current.close();return}if(!ready||!ref.current||!window.google?.maps)return;const center={lat:Number(customerLocation?.lat||DEFAULT_LOCATION.lat),lng:Number(customerLocation?.lng||DEFAULT_LOCATION.lng)};if(!mapRef.current){mapRef.current=new window.google.maps.Map(ref.current,{center,zoom:13,mapTypeControl:false,streetViewControl:false,fullscreenControl:true,gestureHandling:'greedy'});mapRef.current.addListener('click',e=>{if(e.latLng&&onLocationChange)onLocationChange({lat:Number(e.latLng.lat().toFixed(6)),lng:Number(e.latLng.lng().toFixed(6)),label:'Pinned map location'});});}else mapRef.current.setCenter(center);markersRef.current.forEach(m=>m.setMap(null));circlesRef.current.forEach(c=>c.setMap(null));markersRef.current=[];circlesRef.current=[];if(infoRef.current)infoRef.current.close();const customerMarker=new window.google.maps.Marker({map:mapRef.current,position:center,title:'Your location',label:{text:'You',color:'#ffffff',fontWeight:'800'},icon:{path:window.google.maps.SymbolPath.CIRCLE,scale:9,fillColor:'#e65f20',fillOpacity:1,strokeColor:'#ffffff',strokeWeight:2}});markersRef.current.push(customerMarker);const bounds=new window.google.maps.LatLngBounds();bounds.extend(center);const list=businesses.filter(b=>b.latitude!=null&&b.longitude!=null);list.forEach(b=>{const pos={lat:Number(b.latitude),lng:Number(b.longitude)};const marker=new window.google.maps.Marker({map:mapRef.current,position:pos,title:b.name,label:{text:b.name.slice(0,1),color:'#ffffff',fontWeight:'800'}});marker.addListener('click',()=>{if(infoRef.current)infoRef.current.close();infoRef.current=new window.google.maps.InfoWindow({content:`<div style="min-width:210px;font-family:Arial,sans-serif"><strong>${escapeHtml(b.name)}</strong><div style="margin-top:5px;color:#666">${escapeHtml(b.category)} · ${escapeHtml(String(b.distance||'—'))} km away</div>${b.home_visit?`<div style="margin-top:5px">Serves: ${escapeHtml(b.service_area||'Area not specified')}</div><div>Coverage: up to ${escapeHtml(String(b.max_service_radius||'—'))} km</div><div>Visit charge: ₹${Number(b.visit_charge||0).toLocaleString('en-IN')}</div>`:''}<button id="map-open-${b.id}" style="margin-top:8px;padding:6px 9px;border:0;border-radius:7px;background:#e65f20;color:#fff;font-weight:700;cursor:pointer">View details</button></div>`});infoRef.current.open({map:mapRef.current,anchor:marker});window.setTimeout(()=>document.getElementById(`map-open-${b.id}`)?.addEventListener('click',()=>openBusiness(b)),0)});markersRef.current.push(marker);bounds.extend(pos);if(homeServices&&b.home_visit&&Number(b.max_service_radius)>0){const circle=new window.google.maps.Circle({map:mapRef.current,center:pos,radius:Number(b.max_service_radius)*1000,fillColor:'#e65f20',fillOpacity:.08,strokeColor:'#e65f20',strokeOpacity:.28,strokeWeight:1});circlesRef.current.push(circle);}});if(list.length>0)mapRef.current.fitBounds(bounds,{top:40,right:40,bottom:40,left:40});},[ready,expanded,businesses,customerLocation?.lat,customerLocation?.lng,homeServices,openBusiness]);
  return <section className={`map-panel panel map-collapsible ${expanded?'expanded':''}`}><button type="button" className="map-collapse-trigger" onClick={()=>setExpanded(v=>!v)} aria-expanded={expanded}><span className="map-collapse-icon"><MapPin size={22}/></span><span className="map-collapse-copy"><span className="eyebrow">{expanded?'LIVE LOCATION MAP':'EXPLORE ON MAP'}</span><b>{homeServices?'Who serves this area?':'What is nearby?'}</b><small>{expanded?'Tap to hide the map. Click the map to set a location.':'Tap to explore nearby shops and services'}</small></span><span className="map-collapse-chevron">{expanded?'−':'+'}</span></button>{expanded&&(!GOOGLE_MAPS_API_KEY?<div className="map-fallback"><MapPin size={24}/><div><b>Live location map ready</b><p>{mapError||'Google Maps API key is not configured.'}</p><small>Set <code>VITE_GOOGLE_MAPS_API_KEY</code> in <code>frontend/.env</code>, then restart Vite. The map will show your location, nearby businesses and service coverage circles.</small></div></div>:mapError?<div className="error-banner">{mapError}</div>:<div ref={ref} className="google-map" aria-label="Google map showing your location and nearby businesses"/> )}</section>}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}

function HomeServiceRadar({businesses,openBusiness,savedIds,toggleSave,savingIds,t}){
  const providers=businesses.filter(b=>b.home_visit).slice(0,10);
  const angleFor=(index)=>-90+(index*360/Math.max(providers.length,1));
  return <section className="service-radar panel">
    <div className="section-head"><div><span className="eyebrow">HOME SERVICE RADAR</span><h2>Who can come to your area?</h2><small>Coverage, live availability, visit charge and contact details</small></div><span className="radar-live"><span/> LIVE</span></div>
    <div className="radar-layout">
      <div className="radar-map" aria-label="Home service coverage radar">
        <div className="radar-ring ring-1"/><div className="radar-ring ring-2"/><div className="radar-ring ring-3"/><div className="radar-sweep"/>
        <div className="radar-center"><MapPin size={18}/><b>Your area</b><small>Nearby</small></div>
        {providers.map((b,i)=>{const angle=angleFor(i);const coverage=Math.min(43,Math.max(18,Number(b.distance||1)/(Number(b.max_service_radius||10)||10)*43));return <button key={b.id} className="radar-dot-wrap" style={{transform:`rotate(${angle}deg) translateY(-${coverage}%)`}} onClick={()=>openBusiness(b)} title={`${b.name} · ${b.distance} km away`} aria-label={`Open ${b.name}`}><span className="radar-dot"/><span className="radar-label" style={{transform:`rotate(${-angle}deg)`}}>{b.category.replace('Home Services','')}</span></button>})}
      </div>
      <div className="service-provider-list">{providers.map(b=><article className="service-provider" key={b.id} onClick={()=>openBusiness(b)} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openBusiness(b)}}}>
        <div className="service-provider-top"><div className="biz-avatar">{b.name.slice(0,1)}</div><div className="biz-main"><div className="biz-title"><h3>{b.name}</h3>{b.verified?<ShieldCheck size={14}/>:null}</div><p>{b.distance} km away · up to {b.max_service_radius||'—'} km coverage</p></div><SaveButton b={b} saved={savedIds.has(b.id)} saving={savingIds.has(b.id)} toggleSave={toggleSave}/></div>
        <div className="service-meta"><span><MapPin size={13}/>{b.service_area||'Area not specified'}</span><span><Clock3 size={13}/>{b.status_label}</span><span><Phone size={13}/><a href={`tel:${b.phone}`} onClick={e=>e.stopPropagation()}>{b.phone}</a></span><strong>Visit ₹{Number(b.visit_charge||0).toLocaleString('en-IN')}</strong></div>
        <div className="service-tags"><span>{b.is_open?'Available now':'Currently closed'}</span>{b.emergency_service?<span>Emergency</span>:null}{b.appointment_required?<span>Appointment</span>:null}</div>
        <button type="button" className="details-btn" onClick={e=>{e.stopPropagation();openBusiness(b)}}>View service details <ChevronRight size={15}/></button>
      </article>)}</div>
    </div>
  </section>
}
function haversineKmClient(a,b){if(!a||!b||!Number.isFinite(Number(a.lat))||!Number.isFinite(Number(a.lng))||!Number.isFinite(Number(b.lat))||!Number.isFinite(Number(b.lng)))return null;const R=6371,rad=Math.PI/180;const dLat=(Number(b.lat)-Number(a.lat))*rad,dLng=(Number(b.lng)-Number(a.lng))*rad;const x=Math.sin(dLat/2)**2+Math.cos(Number(a.lat)*rad)*Math.cos(Number(b.lat)*rad)*Math.sin(dLng/2)**2;return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function ServiceCoverageMap({business,customerLocation,onLocationChange}){const ref=useRef(null);const mapRef=useRef(null);const customerMarkerRef=useRef(null);const businessMarkerRef=useRef(null);const circleRef=useRef(null);const [ready,setReady]=useState(false);const [mapError,setMapError]=useState('');const provider={lat:Number(business.latitude),lng:Number(business.longitude)};const customer={lat:Number(customerLocation?.lat),lng:Number(customerLocation?.lng)};const distance=haversineKmClient(provider,customer);const radius=Math.max(0,Number(business.max_service_radius)||0);const inCoverage=distance!=null&&radius>0&&distance<=radius;
  useEffect(()=>{let cancelled=false;if(!GOOGLE_MAPS_API_KEY){setMapError('Add VITE_GOOGLE_MAPS_API_KEY to frontend/.env to enable the live coverage map.');return}if(window.google?.maps){setReady(true);return}const existing=document.getElementById('google-maps-script');if(existing){const onLoad=()=>!cancelled&&setReady(true);const onError=()=>!cancelled&&setMapError('Google Maps could not be loaded. Check your API key and Maps JavaScript API access.');existing.addEventListener('load',onLoad);existing.addEventListener('error',onError);return()=>{cancelled=true;existing.removeEventListener('load',onLoad);existing.removeEventListener('error',onError)}}const script=document.createElement('script');script.id='google-maps-script';script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(GOOGLE_MAPS_API_KEY)}&v=weekly`;script.async=true;script.defer=true;script.onload=()=>!cancelled&&setReady(true);script.onerror=()=>!cancelled&&setMapError('Google Maps could not be loaded. Check your API key and Maps JavaScript API access.');document.head.appendChild(script);return()=>{cancelled=true}},[]);
  useEffect(()=>{if(!ready||!ref.current||!window.google?.maps||!Number.isFinite(provider.lat)||!Number.isFinite(provider.lng))return;const center=Number.isFinite(customer.lat)&&Number.isFinite(customer.lng)?customer:provider;if(!mapRef.current){mapRef.current=new window.google.maps.Map(ref.current,{center,zoom:12,mapTypeControl:false,streetViewControl:false,fullscreenControl:true,gestureHandling:'greedy'});mapRef.current.addListener('click',e=>{if(e.latLng&&onLocationChange)onLocationChange({lat:Number(e.latLng.lat().toFixed(6)),lng:Number(e.latLng.lng().toFixed(6)),label:'Pinned map location'});});}else mapRef.current.setCenter(center);if(customerMarkerRef.current)customerMarkerRef.current.setMap(null);if(businessMarkerRef.current)businessMarkerRef.current.setMap(null);if(circleRef.current)circleRef.current.setMap(null);businessMarkerRef.current=new window.google.maps.Marker({map:mapRef.current,position:provider,title:`${business.name} — service provider`,label:{text:'E',color:'#fff',fontWeight:'800'},icon:{path:window.google.maps.SymbolPath.CIRCLE,scale:10,fillColor:'#e65f20',fillOpacity:1,strokeColor:'#fff',strokeWeight:2}});customerMarkerRef.current=new window.google.maps.Marker({map:mapRef.current,position:customer,title:'Your location',label:{text:'You',color:'#fff',fontWeight:'800'},icon:{path:window.google.maps.SymbolPath.CIRCLE,scale:9,fillColor:inCoverage?'#168b5b':'#c43b35',fillOpacity:1,strokeColor:'#fff',strokeWeight:2}});if(radius>0){circleRef.current=new window.google.maps.Circle({map:mapRef.current,center:provider,radius:radius*1000,fillColor:'#e65f20',fillOpacity:.10,strokeColor:'#e65f20',strokeOpacity:.5,strokeWeight:2,clickable:false});}const bounds=new window.google.maps.LatLngBounds();bounds.extend(provider);if(Number.isFinite(customer.lat)&&Number.isFinite(customer.lng))bounds.extend(customer);if(radius>0&&window.google.maps.geometry?.spherical){const circleBounds=new window.google.maps.LatLngBounds();const earthRadius=6371000;for(let i=0;i<360;i+=45){const angle=i*Math.PI/180;const dLat=(radius*1000/earthRadius)*Math.cos(angle);const dLng=(radius*1000/earthRadius)*Math.sin(angle)/Math.cos(provider.lat*Math.PI/180);circleBounds.extend({lat:provider.lat+dLat*180/Math.PI,lng:provider.lng+dLng*180/Math.PI});}bounds.union(circleBounds);}mapRef.current.fitBounds(bounds,{top:48,right:48,bottom:48,left:48});},[ready,business.id,business.name,business.latitude,business.longitude,business.max_service_radius,customerLocation?.lat,customerLocation?.lng,inCoverage,onLocationChange]);
  if(!GOOGLE_MAPS_API_KEY)return <section className="service-coverage-map panel"><div className="map-fallback"><MapPin size={24}/><div><b>Service coverage map ready</b><p>{mapError}</p><small>Set the key in <code>frontend/.env</code> and restart Vite. The profile will then show the provider’s coverage area and your location together.</small></div></div></section>;
  return <section className="service-coverage-map panel"><div className="section-head"><div><span className="eyebrow">SERVICE COVERAGE MAP</span><h2>{business.name} coverage area</h2><small>The orange circle is the maximum service radius. Click the map to test another customer location.</small></div><MapPin size={18}/></div>{mapError?<div className="error-banner">{mapError}</div>:<div ref={ref} className="google-map service-coverage-google-map" aria-label={`Map showing ${business.name} service coverage and your location`}/>}<div className={distance==null?'coverage-result unknown':inCoverage?'coverage-result inside':'coverage-result outside'}><span className="coverage-dot"/><div><b>{distance==null?'Customer location not set':inCoverage?'You are inside this service area':'You are outside this service area'}</b><small>{distance==null?'Use your location button or click the map to set a location.':`You are ${distance.toFixed(1)} km from the provider · coverage is up to ${radius} km.`}</small></div></div><div className="coverage-legend"><span><i className="legend-provider"/> Provider</span><span><i className={inCoverage?'legend-user-in':'legend-user-out'}/> Your location</span><span><i className="legend-area"/> Service area</span></div></section>}
function SaveButton({b,saved,saving,toggleSave}){return <button type="button" className={saved?'save-icon saved':'save-icon'} disabled={saving} onClick={e=>{e.stopPropagation();toggleSave(b)}} aria-pressed={saved} aria-label={saving?'Saving…':saved?`Remove ${b.name} from saved`:`Save ${b.name}`} title={saving?'Saving…':saved?'Saved — click to remove':'Save this business'}>{<Bookmark size={17} fill={saved?'currentColor':'none'} strokeWidth={saved?2.5:2}/>}<span className="sr-only">{saving?'Saving…':saved?`Saved ${b.name}`:`Save ${b.name}`}</span></button>}
function BusinessCard({b,openBusiness,saved,saving,toggleSave,t}){const go=()=>openBusiness(b);return <article className="business-card" onClick={go} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}} tabIndex={0} role="button" aria-label={`View details for ${b.name}`}><div className="card-top"><div className="biz-avatar">{b.name.slice(0,1)}</div><div className="biz-main"><div className="biz-title"><h3>{b.name}</h3>{b.verified?<ShieldCheck size={15}/>:null}</div><p>{b.category} · {b.distance} km</p></div><SaveButton b={b} saved={saved} saving={saving} toggleSave={toggleSave}/></div><div className="status-row"><span className={b.is_open?'status open':'status closed'}>{b.is_open?'● '+t.open:'● '+t.closed}</span><span>{b.status_label}</span></div><div className="mini-items">{b.items?.slice(0,2).map(i=><div key={i.id}><span>{i.name}</span><b>{priceText(i)}</b><em className={`stock ${i.status.toLowerCase()}`}>{!i.availability_verified?'Unverified':i.quantity>0&&i.quantity<5?`Only ${i.quantity} left`:i.status==='IN_STOCK'?'In stock':i.status==='MEDIUM_STOCK'?'Medium stock':i.status==='LOW_STOCK'?'Low stock':'Out of stock'}</em></div>)}</div><div className="card-foot"><span><Star size={14} fill="currentColor"/> {Number(b.rating).toFixed(1)} ({b.reviews_count})</span><button type="button" className="details-btn" onClick={e=>{e.stopPropagation();go()}} aria-label={`View details for ${b.name}`}>View details <ChevronRight size={15}/></button></div></article>}
function Business({business,onBack,saved,toggleSave,user,api,refresh,t,customerLocation,setCustomerLocation}){const [reviewOpen,setReviewOpen]=useState(false);const [body,setBody]=useState('');const [rating,setRating]=useState(5);const [notice,setNotice]=useState('');async function submit(){if(!user){setNotice('Please sign in to review this business.');return}try{const token=localStorage.getItem('mh-token');const r=await fetch(`${API_BASE}/reviews`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({business_id:business.id,rating,body,quality:rating,behaviour:rating,value:rating,accuracy:rating,cleanliness:rating})});if(!r.ok)throw new Error((await r.json()).error);setBody('');setReviewOpen(false);setNotice('Review submitted. It is currently marked unverified until transaction verification exists.');refresh()}catch(e){setNotice(e.message)}}return <div className="stack">
  <button className="back" onClick={onBack}><ArrowLeft size={17}/> Back to discovery</button><section className="profile-hero"><div className="profile-avatar">{business.name.slice(0,1)}</div><div className="profile-copy"><div className="biz-title"><h1>{business.name}</h1>{business.verified?<ShieldCheck size={18}/>:null}</div><p>{business.category} · {business.distance} km away</p><div className={business.is_open?'status open':'status closed'}>{business.status_label}</div></div><SaveButton b={business} saved={saved} saving={false} toggleSave={toggleSave}/></section>
  <div className="info-grid"><div><MapPin size={17}/><span>{business.address}</span></div><div><Phone size={17}/><a href={`tel:${business.phone}`}>{business.phone}</a></div><div><Star size={17}/><span>{Number(business.rating).toFixed(1)} · {business.reviews_count} reviews</span></div><div><Clock3 size={17}/><span>{business.is_open?`Closes ${business.closes_at}`:business.next_open?`Opens ${business.next_open}`:'Closed today'}</span></div></div>
  {business.home_visit?<><ServiceCoverageMap business={business} customerLocation={customerLocation} onLocationChange={setCustomerLocation}/><section className="service-detail-panel panel"><div className="section-head"><div><span className="eyebrow">HOME SERVICE</span><h2>Service coverage</h2></div><MapPin size={18}/></div><div className="service-detail-grid"><div><small>Service area</small><b>{business.service_area||'Area not specified'}</b></div><div><small>Maximum radius</small><b>{business.max_service_radius||'—'} km</b></div><div><small>Visit charge</small><b>₹{Number(business.visit_charge||0).toLocaleString('en-IN')}</b></div><div><small>Availability</small><b>{business.status_label}</b></div><div><small>Booking</small><b>{business.appointment_required?'Appointment required':'Direct visit / call'}</b></div><div><small>Emergency</small><b>{business.emergency_service?'Available':'Not listed'}</b></div></div><a className="primary call" href={`tel:${business.phone}`}><Phone size={16}/> Contact {business.phone}</a></section></>:null}
  <PhotoGallery business={business} user={user} api={api} refresh={refresh}/>
  {business.description&&<section className="panel"><h2>About</h2><p>{business.description}</p>{business.home_visit?<div className="tags"><span>Home visit</span>{business.emergency_service?<span>Emergency service</span>:null}{business.appointment_required?<span>Appointment required</span>:null}</div>:null}</section>}
  <section className="panel"><div className="section-head"><h2>{t.catalog}</h2><small>Freshness matters</small></div><div className="catalog">{business.items?.map(i=><div className="catalog-row" key={i.id}><div><b>{i.name}</b><small>{i.type==='SERVICE'?'Service':'Product'} · {i.availability_verified?'Updated '+relative(i.updated_at):'Availability may be outdated'}</small>{i.description&&<p>{i.description}</p>}</div><div className="catalog-right"><strong>{priceText(i)}</strong><span className={`stock ${i.status.toLowerCase()}`}>{!i.availability_verified?'Availability unverified':i.quantity>0&&i.quantity<5?`Only ${i.quantity} left`:i.status==='IN_STOCK'?'In stock':i.status==='MEDIUM_STOCK'?'Medium stock':i.status==='LOW_STOCK'?'Low stock':'Out of stock'}</span></div></div>)}</div></section>
  <section className="panel"><div className="section-head"><h2>{t.hours}</h2><Clock3 size={18}/></div><div className="hours-list">{business.hours?.map(h=><div key={h.day}><span>{h.day}</span><b>{h.is_closed?'Closed':`${formatTime(h.open_time)} – ${formatTime(h.close_time)}`}</b></div>)}</div></section>
  <section className="panel"><div className="section-head"><div><h2>{t.reviews}</h2><small>Community feedback; not all reviews are verified purchases.</small></div><button className="primary small" onClick={()=>setReviewOpen(!reviewOpen)}>Write review</button></div>{notice&&<div className="notice">{notice}</div>}{reviewOpen&&<div className="review-form"><div className="stars">{[1,2,3,4,5].map(x=><button key={x} onClick={()=>setRating(x)} className={x<=rating?'selected':''}>★</button>)}</div><textarea value={body} onChange={e=>setBody(e.target.value)} placeholder="Share what you actually experienced…"/><button className="primary" onClick={submit}>Submit review</button></div>}<div className="reviews">{business.reviews?.length?business.reviews.map(r=><div className="review" key={r.id}><div className="review-head"><b>{r.reviewer}</b><span>★ {r.rating}</span></div><p>{r.body}</p><small>{r.verification==='VERIFIED'?'Verified experience':'Unverified review'} · {relative(r.created_at)}</small>{r.response&&<div className="response"><b>Business response</b><p>{r.response}</p></div>}</div>):<Empty text="No reviews yet."/>}</div></section>
  <a className="primary call" href={`tel:${business.phone}`}><Phone size={17}/> Call business</a>
</div>}
function Saved({saved,businesses=[],openBusiness,toggleSave,savedIds,api,refreshSaved,t}){const [removing,setRemoving]=useState(new Set());const [expanded,setExpanded]=useState(new Set());const [catalogue,setCatalogue]=useState(businesses);useEffect(()=>{let live=true;api('/businesses').then(rows=>{if(live)setCatalogue(rows)}).catch(()=>{});return()=>{live=false}},[]);async function removeItem(item){setRemoving(prev=>new Set(prev).add(item.id));try{await api(`/saved/item/${item.id}`,{method:'DELETE'});await refreshSaved()}catch{}finally{setRemoving(prev=>{const n=new Set(prev);n.delete(item.id);return n})}}const groups=[...new Map(saved.items.map(i=>[String(i.name||'').trim().toLowerCase(),i])).values()];function matchingShops(item){const key=String(item.name||'').trim().toLowerCase();const matches=catalogue.flatMap(b=>(b.items||[]).filter(x=>String(x.name||'').trim().toLowerCase()===key).map(x=>({business:b,item:x})));if(!matches.some(x=>String(x.business.id)===String(item.business_id)))matches.push({business:{id:item.business_id,name:item.business_name,address:item.address,is_open:item.is_open},item});return matches.filter((x,i,a)=>a.findIndex(y=>String(y.business.id)===String(x.business.id))===i)}function toggleGroup(key){setExpanded(prev=>{const next=new Set(prev);next.has(key)?next.delete(key):next.add(key);return next})}return <div className="stack"><PageTitle title="Saved" icon={<Bookmark/>}/>{saved.businesses.length?saved.businesses.map(b=><BusinessCard key={b.id} b={b} openBusiness={openBusiness} saved={savedIds.has(b.id)} saving={false} toggleSave={toggleSave} t={t}/>):<Empty text="You have not saved any businesses yet."/>}<h2>Saved products</h2><p className="muted">Choose a product to compare the shops that list it, then select the shop you want to visit.</p>{groups.length?groups.map(i=>{const key=String(i.name||'').trim().toLowerCase();const shops=matchingShops(i);const isExpanded=expanded.has(key);return <section className="list-card saved-item-card saved-product-group" key={key}><button type="button" className="saved-item-open" aria-label={`Open ${i.name} shop details`} onClick={()=>openBusiness({id:i.business_id})}><Package size={18}/><span><b>{i.name}</b><small>Saved product · {i.business_name||'Shop details'} · {priceText(i)}</small></span><span className="saved-open-hint">Open shop</span><ChevronRight size={16}/></button><div className="saved-item-actions"><button type="button" className="secondary small" aria-expanded={isExpanded} onClick={()=>toggleGroup(key)}>{isExpanded?'Hide other shops':`Compare ${shops.length} shop${shops.length===1?'':'s'}`}</button><button type="button" className="secondary small" disabled={removing.has(i.id)} onClick={()=>removeItem(i)}>{removing.has(i.id)?'Removing…':'Remove saved item'}</button></div>{isExpanded&&<div className="saved-product-shops">{shops.length===0&&<p className="muted">No other shop listings found yet for this item.</p>}{shops.map(({business,item})=><button type="button" className="saved-shop-option" key={`${business.id}-${item.id}`} onClick={()=>openBusiness(business)}><span><b>{business.name}</b><small>{business.address||'Address not listed'} · {business.is_open?'Open now':'Check opening hours'}</small></span><strong>{priceText(item)}</strong><ChevronRight size={16}/></button>)}</div>}</section>}):<Empty text="No saved products yet."/>}</div>}
function ProductSearchListings({query,businesses,openBusiness}){const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);const listings=businesses.flatMap(b=>(b.items||[]).filter(i=>{const hay=`${i.name} ${i.description||''}`.toLowerCase();return words.every(w=>hay.includes(w))||hay.includes(query.toLowerCase())}).map(i=>({item:i,business:b})));return <section className="panel product-search-results"><div className="section-head"><div><h2>Items matching “{query}”</h2><small>Compare listed prices and shops before visiting</small></div><Package size={18}/></div>{listings.length?listings.map(({item,business})=><button className="product-listing" key={`${business.id}-${item.id}`} onClick={()=>openBusiness(business)}><span className="product-listing-icon"><Package size={18}/></span><span className="product-listing-copy"><b>{item.name}</b><small>{business.name} · {business.address}</small><em>{business.is_open?'Open now':'Currently closed'} · {item.status==='OUT_OF_STOCK'?'Out of stock':item.quantity>0&&item.quantity<5?`Only ${item.quantity} left`:'Check availability with shop'}</em></span><strong>{priceText(item)}</strong><ChevronRight size={16}/></button>):<p className="muted">No exact item listing found for this search in the current local catalog. Try a shorter name or check back as shops add inventory.</p>}</section>}
function Notifications({notifications,refresh,api}){const [selected,setSelected]=useState(null);const open=async n=>{setSelected(n);if(!n.read){try{await api(`/notifications/${n.id}/read`,{method:'PATCH'});refresh()}catch{}}};return <><div className="stack"><PageTitle title="Notifications" icon={<Bell/>}/>{notifications.length?notifications.map(n=><button className={n.read?'notification read':'notification'} key={n.id} onClick={()=>open(n)} aria-label={`Read notification: ${n.title}`}><Bell size={17}/><span><b>{n.title}</b><small>{n.body}</small><em>{relative(n.created_at)}</em></span><ChevronRight size={16} className="notification-arrow"/></button>):<Empty text="No notifications yet."/>}</div>{selected&&<NotificationModal notification={selected} onClose={()=>setSelected(null)}/>}</>}

function NotificationModal({notification,onClose}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="notification-modal" role="dialog" aria-modal="true" aria-labelledby="notification-title"><button className="modal-close" onClick={onClose} aria-label="Close notification"><X size={18}/></button><div className="notification-modal-icon"><Bell size={21}/></div><div><h2 id="notification-title">{notification.title}</h2><small>{relative(notification.created_at)}</small></div><p>{notification.body}</p><button className="primary" onClick={onClose}>Close</button></section></div>}
function Profile({user,logout,setTheme,theme,setPage}){return <div className="stack"><PageTitle title="Profile" icon={<User/>}/><section className="profile-card"><div className="big-avatar">{(user?.name||'U')[0]}</div><h2>{user?.name}</h2><p>{user?.email}</p><span className="role-badge">{user?.role.replace('_',' ')}</span></section><section className="panel"><h2>Preferences</h2><label className="setting"><span><Moon size={17}/>Theme</span><select value={theme} onChange={e=>setTheme(e.target.value)}><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label></section>{user?.role==='BUSINESS_OWNER'&&<button className="primary" onClick={()=>setPage('dashboard')}>Open business dashboard</button>}{user?.role==='ADMIN'&&<button className="primary" onClick={()=>setPage('admin')}>Open admin dashboard</button>}<button className="danger-btn" onClick={logout}><LogOut size={17}/>Log out</button></div>}
function BusinessDashboard({api,t,logout}){const [biz,setBiz]=useState(null);const [demand,setDemand]=useState(null);const [tab,setTab]=useState('overview');const [editing,setEditing]=useState(false);const [form,setForm]=useState({});const [hours,setHours]=useState([]);const [closedToday,setClosedToday]=useState(false);const [specialNote,setSpecialNote]=useState('');const [reviewReply,setReviewReply]=useState({});const [msg,setMsg]=useState('');useEffect(()=>{(async()=>{try{const b=await api('/business/me');setBiz(b);setForm(b);setHours(b.hours||[]);try{const special=await api(`/business/${b.id}/special-hours/today`);setClosedToday(!!special.is_closed);setSpecialNote(special.note||'')}catch{}setDemand(await api('/dashboard/demand'))}catch(e){setMsg(e.message)}})()},[]);if(!biz)return <Loading/>;async function saveBiz(){await api(`/business/${biz.id}`,{method:'PATCH',body:JSON.stringify(form)});setBiz(await api('/business/me'));setEditing(false);setMsg('Business profile updated.')};async function saveHours(){await api(`/business/${biz.id}/hours`,{method:'PUT',body:JSON.stringify({hours})});setBiz(await api('/business/me'));setMsg('Weekly opening hours updated.')};async function saveSpecialHours(){await api(`/business/${biz.id}/special-hours/today`,{method:'PUT',body:JSON.stringify({is_closed:closedToday,note:specialNote})});setBiz(await api('/business/me'));setMsg(closedToday?'Your shop is marked closed for today only.':'Today-only closure removed; your weekly schedule applies again.')};async function saveQuantity(i,value){const quantity=Math.max(0,Number(value)||0);await api(`/items/${i.id}`,{method:'PATCH',body:JSON.stringify({quantity})});setBiz(await api('/business/me'));setMsg(`${i.name} stock updated to ${quantity} item${quantity===1?'':'s'}.`)};async function reply(id){await api(`/reviews/${id}/response`,{method:'POST',body:JSON.stringify({body:reviewReply[id]})});setBiz(await api('/business/me'));setReviewReply(x=>({...x,[id]:''}))}
return <div className="stack"><PageTitle title={t.dashboard} icon={<Store/>}/><div className="dashboard-head"><div><span className="eyebrow">VERIFIED OWNER</span><h1>{biz.name}</h1><p>{biz.profile_completeness}% profile complete</p></div><button className="danger-outline" onClick={logout}><LogOut size={16}/>Logout</button></div><div className="tabs">{[['overview','Overview'],['inventory','Inventory'],['hours','Hours'],['photos','Shop photos'],['reviews','Reviews'],['demand','Demand']].map(x=><button className={tab===x[0]?'tab active':'tab'} onClick={()=>setTab(x[0])} key={x[0]}>{x[1]}</button>)}</div>{msg&&<div className="notice">{msg}</div>}
{tab==='overview'&&<><div className="metric-grid"><Metric label="Rating" value={biz.rating}/><Metric label="Reviews" value={biz.reviews_count}/><Metric label="Items" value={biz.items.length}/><Metric label="Status" value={biz.is_open?'Open':'Closed'}/></div><section className="panel"><div className="section-head"><h2>Business profile</h2><button className="icon-btn" onClick={()=>setEditing(!editing)}><Edit3 size={16}/></button></div>{editing?<div className="form-grid">{['name','category','phone','address','description','service_area','max_service_radius','visit_charge','latitude','longitude'].map(k=><label key={k}>{k.replace('_',' ')}<input type={['max_service_radius','visit_charge'].includes(k)?'number':'text'} min={['max_service_radius','visit_charge'].includes(k)?'0':undefined} value={form[k]??''} onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}{biz.home_visit?<><label className="check-field"><input type="checkbox" checked={!!form.home_visit} onChange={e=>setForm({...form,home_visit:e.target.checked?1:0})}/> Home visit</label><label className="check-field"><input type="checkbox" checked={!!form.emergency_service} onChange={e=>setForm({...form,emergency_service:e.target.checked?1:0})}/> Emergency service</label><label className="check-field"><input type="checkbox" checked={!!form.appointment_required} onChange={e=>setForm({...form,appointment_required:e.target.checked?1:0})}/> Appointment required</label></>:null}<button className="primary" onClick={saveBiz}><Save size={16}/>Save changes</button></div>:<p>{biz.description||'Add a description to improve your listing.'}</p>}</section></>}
{tab==='inventory'&&<section className="panel"><div className="section-head"><div><h2>Inventory</h2><small>Enter the exact quantity. Customers only see the exact number when fewer than 5 remain.</small></div><AddItem api={api} businessId={biz.id} refresh={async()=>setBiz(await api('/business/me'))}/></div>{biz.items.map(i=><div className="inventory-row" key={i.id}><div><b>{i.name}</b><small>{priceText(i)} · Updated {relative(i.updated_at)}</small></div><div className="inventory-controls"><label><span>Items</span><input type="number" min="0" value={i.quantity??0} onChange={e=>setBiz({...biz,items:biz.items.map(x=>x.id===i.id?{...x,quantity:e.target.value}:x)})} onBlur={e=>saveQuantity(i,e.target.value)}/></label><span className={`stock-button ${i.status.toLowerCase()}`}>{i.status==='IN_STOCK'?'HIGH STOCK':i.status==='MEDIUM_STOCK'?'MEDIUM STOCK':i.status==='LOW_STOCK'?'LOW STOCK':'OUT OF STOCK'}</span></div></div>)}</section>}
{tab==='hours'&&<><section className="panel special-hours-panel"><div className="section-head"><div><h2>One-time change for today</h2><small>This does not change your regular weekly schedule.</small></div><CalendarClock size={20}/></div><label className="check-field closed-today-toggle"><input type="checkbox" checked={closedToday} onChange={e=>setClosedToday(e.target.checked)}/><span><b>Closed today</b><small>Mark your shop closed for today only. Your normal hours resume tomorrow.</small></span></label><label className="special-note-label">Optional note for customers<input value={specialNote} onChange={e=>setSpecialNote(e.target.value)} maxLength={160} placeholder="e.g. Personal work — reopening tomorrow"/></label><button className="primary" onClick={saveSpecialHours}><Save size={16}/>{closedToday?'Save today’s closure':'Apply today’s hours'}</button></section><section className="panel"><div className="section-head"><h2>Weekly hours</h2><button className="primary small" onClick={saveHours}><Save size={15}/>Save</button></div>{hours.map((h,idx)=><div className="hour-editor" key={h.day}><b>{h.day}</b><label className="switch"><input type="checkbox" checked={!h.is_closed} onChange={e=>setHours(hours.map((x,i)=>i===idx?{...x,is_closed:!e.target.checked}:x))}/><span/></label>{!h.is_closed&&<><input type="time" value={h.open_time||''} onChange={e=>setHours(hours.map((x,i)=>i===idx?{...x,open_time:e.target.value}:x))}/><span>to</span><input type="time" value={h.close_time||''} onChange={e=>setHours(hours.map((x,i)=>i===idx?{...x,close_time:e.target.value}:x))}/></>}</div>)}</section></>}
{tab==='photos'&&<section className="panel"><PhotoGallery business={biz} user={{role:'BUSINESS_OWNER'}} dashboard api={api} refresh={async()=>setBiz(await api('/business/me'))}/></section>}
{tab==='reviews'&&<section className="panel"><h2>Reviews</h2>{biz.reviews?.length?biz.reviews.map(r=><div className="review" key={r.id}><div className="review-head"><b>{r.reviewer}</b><span>★ {r.rating}</span></div><p>{r.body}</p>{r.response?<div className="response"><b>Your response</b><p>{r.response}</p></div>:<><textarea value={reviewReply[r.id]||''} onChange={e=>setReviewReply({...reviewReply,[r.id]:e.target.value})} placeholder="Respond professionally…"/><button className="primary small" onClick={()=>reply(r.id)}>Respond</button></>}</div>):<Empty text="No reviews yet."/>}</section>}
{tab==='demand'&&<section className="panel"><div className="section-head"><div><h2>Local demand</h2><small>7-day period vs previous 7-day period. Privacy threshold: 5 events.</small></div><BarChart3/></div>{demand?.insights?.length?demand.insights.map(x=><div className="demand-row" key={x.query}><div><b>{x.query}</b><small>{x.searches} searches · previous {x.previous}</small></div><strong>{x.increase===null?'New':`${x.increase>0?'+':''}${x.increase}%`}</strong></div>):<Empty text="Not enough data yet."/>}<p className="muted">Demo activity is clearly marked as seeded; production demand must come from aggregated application events.</p></section>}
</div>}
function AdminDashboard({api}){const [data,setData]=useState(null);const [claims,setClaims]=useState([]);const [reports,setReports]=useState([]);useEffect(()=>{(async()=>{setData(await api('/admin/overview'));setClaims(await api('/admin/claims'));setReports(await api('/admin/reports'))})()},[]);if(!data)return <Loading/>;return <div className="stack"><PageTitle title="Admin moderation" icon={<ShieldCheck/>}/><div className="metric-grid"><Metric label="Users" value={data.users}/><Metric label="Businesses" value={data.businesses}/><Metric label="Pending claims" value={data.pendingClaims}/><Metric label="Open reports" value={data.openReports}/></div><section className="panel"><h2>Business claims</h2>{claims.length?claims.map(c=><div className="admin-row" key={c.id}><div><b>{c.business_name}</b><small>{c.email} · {c.status}</small></div>{c.status==='PENDING'&&<button className="primary small" onClick={async()=>{await api(`/admin/claims/${c.id}`,{method:'PATCH',body:JSON.stringify({status:'APPROVED'})});setClaims(claims.map(x=>x.id===c.id?{...x,status:'APPROVED'}:x))}}>Approve</button>}</div>):<Empty text="No pending claims."/>}</section><section className="panel"><h2>Reports</h2>{reports.length?reports.map(r=><div className="admin-row" key={r.id}><div><b>{r.target_type} #{r.target_id}</b><small>{r.reason} · {r.status}</small></div>{r.status==='OPEN'&&<button className="secondary small" onClick={async()=>{await api(`/admin/reports/${r.id}`,{method:'PATCH',body:JSON.stringify({status:'RESOLVED',resolution:'Reviewed by admin'})});setReports(reports.map(x=>x.id===r.id?{...x,status:'RESOLVED'}:x))}}>Resolve</button>}</div>):<Empty text="No reports."/>}</section></div>}
function PhotoGallery({business,user,refresh,dashboard,api}){
  const [open,setOpen]=useState(false),[file,setFile]=useState(null),[preview,setPreview]=useState(''),[caption,setCaption]=useState(''),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');
  const inputRef=useRef(null);
  const canPost=!!user;
  async function choose(e){
    const f=e.target.files?.[0];
    if(!f)return;
    setMsg('');
    if(!['image/jpeg','image/png','image/webp'].includes(f.type)){setMsg('Please choose a JPG, PNG or WebP image.');return}
    if(f.size>8*1024*1024){setMsg('Please choose an image smaller than 8 MB.');return}
    try{const data=await compressImage(f);setFile(f);setPreview(data)}catch{setMsg('Could not read this image. Please try another photo.')}
  }
  async function upload(){
    if(!preview||!canPost)return;
    setBusy(true);setMsg('');
    try{
      const token=localStorage.getItem('mh-token');
      const r=await fetch(`${API_BASE}/businesses/${business.id}/photos`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({image_data:preview,caption})});
      const d=await r.json().catch(()=>({}));
      if(!r.ok)throw new Error(d.error||'Could not upload photo');
      setFile(null);setPreview('');setCaption('');
      if(inputRef.current)inputRef.current.value='';
      setOpen(false);setMsg('Photo posted successfully.');
      await refresh();
    }catch(e){setMsg(e.message)}finally{setBusy(false)}
  }
  async function remove(id){if(!confirm('Remove this shop photo?'))return;try{await api(`/business-photos/${id}`,{method:'DELETE'});await refresh()}catch(e){setMsg(e.message)}}
  function closeUploader(){setOpen(false);setPreview('');setFile(null);setCaption('');if(inputRef.current)inputRef.current.value=''}
  return <section className="panel photo-panel">
    <div className="section-head"><div><h2><Camera size={18}/> Shop photos</h2><small>Photos shared by the shopkeeper and local customers.</small></div>{canPost?<button type="button" className="primary small" onClick={()=>{setMsg('');setOpen(v=>!v)}}><Camera size={15}/> Post photo</button>:null}</div>
    {msg&&<div className="notice">{msg}</div>}
    {open&&<div className="photo-uploader">
      <input ref={inputRef} id={`shop-photo-${business.id}`} className="photo-file-input" type="file" accept="image/jpeg,image/png,image/webp" onChange={choose}/>
      <div className={preview?'photo-preview has-image':'photo-preview'}>{preview?<img src={preview} alt="Selected shop"/>:<><Camera size={30}/><b>Select a shop photo</b><small>JPG, PNG or WebP · max 8 MB</small></>}</div>
      <div className="inline-form photo-actions"><button type="button" className="secondary small" onClick={()=>inputRef.current?.click()}><Camera size={15}/>{file?'Change photo':'Choose photo'}</button><button type="button" className="primary small" disabled={!preview||busy} onClick={upload}>{busy?'Uploading…':'Upload photo'}</button><button type="button" className="icon-btn" onClick={closeUploader} title="Cancel"><X size={16}/></button></div>
      <input className="caption-input" placeholder="Caption (optional)" value={caption} onChange={e=>setCaption(e.target.value)} maxLength={180}/>
    </div>}
    {business.photos?.length?<div className="photo-grid">{business.photos.map(p=><figure className="shop-photo" key={p.id}><img src={`${API_BASE.replace(/\/api$/,'')}${p.image_url}`} alt={p.caption||`Photo of ${business.name}`}/><figcaption><b>{p.uploader}</b><span>{p.uploader_role==='BUSINESS_OWNER'?'Shopkeeper':'Customer'} · {relative(p.created_at)}</span>{p.caption&&<p>{p.caption}</p>}{dashboard||p.user_id===user?.id?<button className="photo-remove" onClick={()=>remove(p.id)} title="Remove photo"><X size={14}/></button>:null}</figcaption></figure>)}</div>:<Empty text="No shop photos yet. Be the first to show customers what this place looks like."/>}
  </section>
}
function compressImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const max=1400;const scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.78))};img.src=reader.result};reader.readAsDataURL(file)})}

function AddItem({api,businessId,refresh}){const [open,setOpen]=useState(false),[name,setName]=useState(''),[price,setPrice]=useState(''),[quantity,setQuantity]=useState(''),[type,setType]=useState('PRODUCT');if(!open)return <button className="primary small" onClick={()=>setOpen(true)}><Plus size={15}/>Add item</button>;return <div className="inline-form"><input placeholder="Item/service" value={name} onChange={e=>setName(e.target.value)}/><input placeholder="₹ price" type="number" value={price} onChange={e=>setPrice(e.target.value)}/><input placeholder="Items in stock" type="number" min="0" value={quantity} onChange={e=>setQuantity(e.target.value)}/><select value={type} onChange={e=>setType(e.target.value)}><option>PRODUCT</option><option>SERVICE</option></select><button className="primary small" onClick={async()=>{await api('/items',{method:'POST',body:JSON.stringify({business_id:businessId,name,price:Number(price),quantity:Number(quantity)||0,type})});setOpen(false);setName('');setPrice('');setQuantity('');refresh()}}>Save</button><button className="icon-btn" onClick={()=>setOpen(false)}><X size={16}/></button></div>}
function AuthModal({onClose,onLogin,onRegister}){const [mode,setMode]=useState('login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[role,setRole]=useState('CUSTOMER'),[err,setErr]=useState('');async function submit(e){e.preventDefault();try{if(mode==='login')await onLogin(email,password);else await onRegister({name,email,password,role,location:'Bada Bazaar, Indore'})}catch(x){setErr(x.message)}}return <div className="modal-backdrop"><form className="auth-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={onClose}><X/></button><span className="eyebrow">MARKET HUB</span><h2>{mode==='login'?'Welcome back':'Create account'}</h2><p>{mode==='login'?'Sign in to save, review, or manage your business.':'Choose the account type that fits you.'}</p>{err&&<div className="error-banner">{err}</div>}{mode==='register'&&<input placeholder="Full name" value={name} onChange={e=>setName(e.target.value)} required/>}<input type="email" placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} required/><input type="password" placeholder="Password" value={password} onChange={e=>setPassword(e.target.value)} required/>{mode==='register'&&<select value={role} onChange={e=>setRole(e.target.value)}><option value="CUSTOMER">Customer</option><option value="BUSINESS_OWNER">Business owner</option></select>}<button className="primary full">{mode==='login'?'Sign in':'Create account'}</button>{mode==='login'&&<div className="demo-buttons"><button type="button" onClick={()=>onLogin(DEMO.CUSTOMER.email,DEMO.CUSTOMER.password)}>Try Demo Customer</button><button type="button" onClick={()=>onLogin(DEMO.BUSINESS_OWNER.email,DEMO.BUSINESS_OWNER.password)}>Try Demo Business</button></div>}<button type="button" className="link-btn" onClick={()=>setMode(mode==='login'?'register':'login')}>{mode==='login'?"Don't have an account? Create one":"Already have an account? Sign in"}</button><small className="muted">Demo accounts are intentionally public. Never expose real credentials in client code.</small></form></div>}
function PageTitle({title,icon}){return <div className="page-title"><span>{icon}</span><h1>{title}</h1></div>}
function Metric({label,value}){return <div className="metric"><small>{label}</small><strong>{value}</strong></div>}
function Loading(){return <div className="loading"><RefreshCw className="spin" size={18}/>Loading local information…</div>}
function Empty({text}){return <div className="empty"><Search size={22}/><b>{text}</b></div>}
function priceText(i){if(i.price_type==='ON_REQUEST')return 'Price on request';if(i.price_type==='STARTING')return `Starting at ₹${i.price_min??i.price}`;if(i.price_type==='FROM')return `From ₹${i.price_min??i.price}`;if(i.price_type==='RANGE')return `₹${i.price_min}–₹${i.price_max}`;return i.price==null?'Contact for price':`₹${i.price}`}
function relative(ts){const m=Math.max(0,Math.round((Date.now()-new Date(ts).getTime())/60000));if(m<60)return `${m} min ago`;const h=Math.round(m/60);if(h<24)return `${h} hr ago`;return `${Math.round(h/24)} day ago`}
function formatTime(v){if(!v)return '';const [h,m]=v.split(':').map(Number);const d=new Date(2000,0,1,h,m);return d.toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}

export default App;
